create table public.admins (singleton boolean primary key default true check(singleton), user_id uuid unique not null references auth.users(id));
create table public.tournaments (id uuid primary key default gen_random_uuid(), name text not null, published boolean not null default false, group_count int not null check(group_count>0), teams_per_group int not null check(teams_per_group>=2), max_subs int not null default 2 check(max_subs>=0), tie_rule text not null default 'penalties' check(tie_rule in ('penalties','extra_time_penalties')));
create table public.teams (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id), name text not null, group_no int not null check(group_no>0), unique(tournament_id,name), unique(tournament_id,id));
create table public.players (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id), name text not null, team_id uuid, foreign key(tournament_id,team_id) references public.teams(tournament_id,id), unique(tournament_id,id));
create table public.matches (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id), home_id uuid not null, away_id uuid, stage text not null check(stage in ('group','knockout')), round_no int not null default 1 check(round_no>0), starts_at timestamptz, home_score int check(home_score>=0), away_score int check(away_score>=0), home_penalties int check(home_penalties>=0), away_penalties int check(away_penalties>=0), official boolean not null default false, foreign key(tournament_id,home_id) references public.teams(tournament_id,id), foreign key(tournament_id,away_id) references public.teams(tournament_id,id), check(home_id<>away_id), check(not official or (home_score is not null and away_score is not null)), unique(tournament_id,id));
create table public.events (id uuid primary key default gen_random_uuid(), tournament_id uuid not null references public.tournaments(id), name text not null, starts_at timestamptz not null);
create table public.substitutes (tournament_id uuid not null, match_id uuid not null, player_id uuid not null, team_id uuid not null, primary key(match_id,player_id), foreign key(tournament_id,match_id) references public.matches(tournament_id,id), foreign key(tournament_id,player_id) references public.players(tournament_id,id), foreign key(tournament_id,team_id) references public.teams(tournament_id,id));
alter table public.admins enable row level security;
revoke all on public.admins from anon, authenticated;
grant select on public.admins to authenticated;
create policy own_admin on public.admins for select to authenticated using(user_id=(select auth.uid()));
do $$ declare t text; begin foreach t in array array['tournaments','teams','players','matches','events','substitutes'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); execute format('grant select,insert,update,delete on public.%I to authenticated',t); execute format('create policy admin_access on public.%I for all to authenticated using (exists(select 1 from public.admins where user_id=(select auth.uid()))) with check (exists(select 1 from public.admins where user_id=(select auth.uid())))',t); end loop; end $$;
grant select on public.tournaments,public.teams,public.matches,public.events to anon;
create policy published_read on public.tournaments for select to anon,authenticated using(published);
do $$ declare t text; begin foreach t in array array['teams','matches','events'] loop execute format('create policy published_read on public.%I for select to anon,authenticated using(exists(select 1 from public.tournaments where id=tournament_id and published))',t); end loop; end $$;
